/**
 * Open Graph preview image, generated by the app itself (no external assets).
 * 1200×630, midnight gradient, the two typefaces we already self-host.
 */
import { ImageResponse } from 'next/og';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';

export const runtime = 'nodejs';
export const alt = 'For Samiya — a letter, a question, and a countdown';
export const size = { width: 1200, height: 630 };
export const contentType = 'image/png';

async function loadFont(file: string): Promise<ArrayBuffer> {
  const path = join(process.cwd(), 'src', 'fonts', file);
  const buffer = await readFile(path);
  return buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength) as ArrayBuffer;
}

export default async function OpengraphImage(): Promise<ImageResponse> {
  const [playfair, playfairItalic, inter] = await Promise.all([
    loadFont('playfair-og.ttf'),
    loadFont('playfair-og-italic.ttf'),
    loadFont('inter-og.ttf'),
  ]);

  return new ImageResponse(
    (
      <div
        style={{
          width: '100%',
          height: '100%',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          alignItems: 'center',
          position: 'relative',
          background: 'radial-gradient(120% 90% at 50% -10%, #241339 0%, #0B0713 60%, #070410 100%)',
          fontFamily: 'Inter',
          color: '#F4EEFB',
        }}
      >
        <div
          style={{
            position: 'absolute',
            top: -180,
            left: -120,
            width: 560,
            height: 560,
            borderRadius: 560,
            background: 'radial-gradient(circle, rgba(168,85,247,0.42), rgba(168,85,247,0) 66%)',
            display: 'flex',
          }}
        />
        <div
          style={{
            position: 'absolute',
            bottom: -220,
            right: -140,
            width: 620,
            height: 620,
            borderRadius: 620,
            background: 'radial-gradient(circle, rgba(255,77,141,0.34), rgba(255,77,141,0) 68%)',
            display: 'flex',
          }}
        />

        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 14,
            fontSize: 20,
            letterSpacing: 10,
            textTransform: 'uppercase',
            color: 'rgba(255,217,160,0.9)',
          }}
        >
          <span>A LETTER FOR YOU</span>
        </div>

        <div
          style={{
            marginTop: 28,
            fontFamily: 'Playfair',
            fontSize: 128,
            lineHeight: 1,
            color: '#FFFFFF',
            display: 'flex',
          }}
        >
          For Samiya
        </div>

        <div
          style={{
            marginTop: 26,
            fontFamily: 'Playfair',
            fontStyle: 'italic',
            fontSize: 44,
            color: '#FF9DBF',
            display: 'flex',
          }}
        >
          A question, and a countdown.
        </div>

        <div
          style={{
            marginTop: 44,
            display: 'flex',
            alignItems: 'center',
            gap: 18,
            fontSize: 22,
            color: 'rgba(255,255,255,0.45)',
          }}
        >
          <span
            style={{
              width: 10,
              height: 10,
              borderRadius: 10,
              background: '#FF4D8D',
              display: 'flex',
            }}
          />
          <span>one evening, chosen by you</span>
        </div>
      </div>
    ),
    {
      ...size,
      fonts: [
        { name: 'Playfair', data: playfair, style: 'normal', weight: 400 },
        { name: 'Playfair', data: playfairItalic, style: 'italic', weight: 400 },
        { name: 'Inter', data: inter, style: 'normal', weight: 400 },
      ],
    },
  );
}
